"""Copy Verge's docs from their code repositories into the site, as Zola pages.

    python3 .github/verge-docs.py SITE [--repo NAME=PATH ...]

SITE is this repository. The docs to copy, their order and their addresses are in
content/verge/_index.md's front matter. Each comes from a checkout of its repository: by default the
directory beside SITE with the repository's name, or the one --repo names. The pages go to
content/verge/docs/, which is generated and ignored by git.

A doc keeps reading on GitHub, so its links are relative links between files. Here a link to another
doc in the list becomes a link to that doc's page (Zola's @/ link, which zola build checks), and a
link to any other file of the repository becomes a link to that file on GitHub. A file name that
names a doc in the list, in a code span such as `HOST-INTERFACE.md` or bare in the text, links the
same way. The doc's
first heading is its title, which the page prints itself, so it is dropped.
"""
import argparse
import json
import pathlib
import re
import shutil
import sys
import tomllib

GITHUB = "https://github.com/Escapement-Project"
MARKER = "# Generated by .github/verge-docs.py; edit the docs in their repositories."

ap = argparse.ArgumentParser()
ap.add_argument("site", type=pathlib.Path)
ap.add_argument("--repo", action="append", default=[], metavar="NAME=PATH")
args = ap.parse_args()

index = (args.site / "content" / "verge" / "_index.md").read_text()
front = re.match(r"\+\+\+\n(.*?)\n\+\+\+", index, re.S)
if not front:
    sys.exit("content/verge/_index.md has no +++ front matter")
groups = tomllib.loads(front.group(1))["extra"]["groups"]
repos = {name: pathlib.Path(path) for name, path in (r.split("=", 1) for r in args.repo)}

def checkout(repo: str) -> pathlib.Path:
    return repos.get(repo) or args.site.resolve().parent / repo

docs = [dict(d, group=g["title"]) for g in groups for d in g["docs"]]
by_source = {(d["repo"], d["path"]): d for d in docs}

out = args.site / "content" / "verge" / "docs"
if out.exists():
    first = (out / "_index.md").read_text().splitlines()[1:2] if (out / "_index.md").exists() else []
    if first != [MARKER]:
        sys.exit(f"{out} exists and was not made by this script; move it away first")
    shutil.rmtree(out)
out.mkdir()
(out / "_index.md").write_text(
    f'+++\n{MARKER}\ntitle = "Docs"\nsort_by = "weight"\ntemplate = "verge-docs.html"\ninsert_anchor_links = "right"\n+++\n'
)

def target(doc: dict, link: str) -> str:
    """Where a link in `doc` goes on the site: a doc's page, a file on GitHub, or as written."""
    if re.match(r"[a-z][a-z0-9+.-]*:|#|/", link):
        return link
    path, _, anchor = link.partition("#")
    resolved = (pathlib.PurePosixPath(doc["path"]).parent / path).as_posix()
    # Collapse ./ and ../ without touching the filesystem.
    parts: list[str] = []
    for part in resolved.split("/"):
        if part == "..":
            parts and parts.pop()
        elif part not in ("", "."):
            parts.append(part)
    resolved = "/".join(parts)
    hash_ = f"#{anchor}" if anchor else ""
    linked = by_source.get((doc["repo"], resolved))
    if linked:
        return f"@/verge/docs/{linked['name']}.md{hash_}"
    return f"{GITHUB}/{doc['repo']}/blob/HEAD/{resolved}{hash_}"

def rewrite(doc: dict, text: str) -> str:
    lines, fenced = [], False
    for line in text.splitlines():
        if line.lstrip().startswith("```"):
            fenced = not fenced
        elif not fenced:
            line = re.sub(r"(\]\()([^)\s]+)(\))", lambda m: m[1] + target(doc, m[2]) + m[3], line)
            line = re.sub(r"(?<!\[)`([A-Z][A-Z0-9-]*\.md)`(?!\])",
                          lambda m: f"[`{m[1]}`]({target(doc, m[1])})" if (doc["repo"], m[1]) in by_source else m[0], line)
            # A bare file name in the text, outside code spans and links.
            parts = re.split(r"(`[^`]*`|\[[^\]]*\]\([^)]*\))", line)
            line = "".join(part if i % 2 else re.sub(
                r"(?<![\w/.-])([A-Z][A-Z0-9-]*\.md)\b",
                lambda m: f"[{m[1]}]({target(doc, m[1])})" if (doc["repo"], m[1]) in by_source else m[0], part)
                for i, part in enumerate(parts))
        lines.append(line)
    return "\n".join(lines) + "\n"

copied, coming = 0, []
for weight, doc in enumerate(docs, 1):
    source = checkout(doc["repo"]) / doc["path"]
    if not source.is_file():
        coming.append(f"{doc['repo']}/{doc['path']}")
        continue
    text = source.read_text()
    text = re.sub(r"\A# .*\n+", "", text)
    meta = {
        "title": doc["title"],
        "description": doc["about"],
        "weight": weight,
        "template": "verge-doc.html",
    }
    extra = {"group": doc["group"], "source": f"{GITHUB}/{doc['repo']}/blob/HEAD/{doc['path']}", "repo": doc["repo"]}
    # A JSON string is a valid TOML basic string.
    head = "\n".join(f"{k} = {json.dumps(v)}" for k, v in meta.items())
    head += "\n[extra]\n" + "\n".join(f"{k} = {json.dumps(v)}" for k, v in extra.items())
    (out / f"{doc['name']}.md").write_text(f"+++\n{head}\n+++\n\n{rewrite(doc, text)}")
    copied += 1

print(f"copied {copied} docs; not written yet: {', '.join(coming) or 'none'}")
